//#region src/errors.ts
var PostGuardError = class extends Error {
	constructor(message, options) {
		super(message, options);
		this.name = "PostGuardError";
	}
};
var NetworkError = class extends PostGuardError {
	status;
	body;
	constructor(message, status, body) {
		super(message);
		this.name = "NetworkError";
		this.status = status;
		this.body = body;
	}
};
var YiviNotInstalledError = class extends PostGuardError {
	constructor() {
		super("Install @privacybydesign/yivi-core, @privacybydesign/yivi-web, and @privacybydesign/yivi-client to use Yivi features.");
		this.name = "YiviNotInstalledError";
	}
};
var DecryptionError = class extends PostGuardError {
	constructor(message) {
		super(message);
		this.name = "DecryptionError";
	}
};
var IdentityMismatchError = class extends DecryptionError {
	constructor() {
		super("Identity mismatch: the Yivi attributes did not match the encryption policy.");
		this.name = "IdentityMismatchError";
	}
};
