//#region src/api/pkg.ts
function mergeHeaders(base, extra) {
	if (!base && !extra) return void 0;
	return {
		...Object.fromEntries(new Headers(base)),
		...Object.fromEntries(new Headers(extra))
	};
}
/** Fetch the master public key from the PKG server */
async function fetchMPK(pkgUrl, headers) {
	const response = await fetch(`${pkgUrl}/v2/parameters`, { headers: headers ? new Headers(headers) : void 0 });
	if (!response.ok) {
		const body = await response.text();
		throw new NetworkError(`Failed to fetch PKG parameters`, response.status, body);
	}
	return (await response.json()).publicKey;
}
/** Fetch the verification key for signature verification (used in decryption) */
async function fetchVerificationKey(pkgUrl, headers) {
	const response = await fetch(`${pkgUrl}/v2/sign/parameters`, { headers: headers ? new Headers(headers) : void 0 });
	if (!response.ok) {
		const body = await response.text();
		throw new NetworkError(`Failed to fetch sign parameters`, response.status, body);
	}
	return (await response.json()).publicKey;
}
/** Fetch signing keys using an API key (PostGuard for Business) */
async function fetchSigningKeysWithApiKey(pkgUrl, apiKey, headers) {
	const response = await fetch(`${pkgUrl}/v2/irma/sign/key`, {
		method: "POST",
		headers: new Headers(mergeHeaders(headers, {
			"Content-Type": "application/json",
			Authorization: `Bearer ${apiKey}`
		})),
		body: JSON.stringify({ pubSignId: [{ t: "pbdf.sidn-pbdf.email.email" }] })
	});
	if (!response.ok) {
		const body = await response.text();
		throw new NetworkError(`Failed to fetch signing keys`, response.status, body);
	}
	return response.json();
}
/** Retrieve a User Secret Key (USK) using a JWT */
async function getUSK(pkgUrl, jwt, timestamp, headers) {
	const response = await fetch(`${pkgUrl}/v2/irma/key/${timestamp}`, { headers: new Headers(mergeHeaders(headers, { Authorization: `Bearer ${jwt}` })) });
	if (!response.ok) {
		const body = await response.text();
		throw new NetworkError(`Failed to fetch USK`, response.status, body);
	}
	const json = await response.json();
	if (json.status !== "DONE" || json.proofStatus !== "VALID") throw new NetworkError(`PKG session not DONE and VALID`, 0, JSON.stringify(json));
	return json.key;
}
/** Retrieve signing keys using a JWT */
async function getSigningKeysWithJwt(pkgUrl, jwt, keyRequest, headers) {
	const response = await fetch(`${pkgUrl}/v2/irma/sign/key`, {
		method: "POST",
		headers: new Headers(mergeHeaders(headers, {
			"Content-Type": "application/json",
			Authorization: `Bearer ${jwt}`
		})),
		body: JSON.stringify(keyRequest)
	});
	if (!response.ok) {
		const body = await response.text();
		throw new NetworkError(`Failed to fetch signing keys`, response.status, body);
	}
	const json = await response.json();
	if (json.status !== "DONE" || json.proofStatus !== "VALID") throw new NetworkError(`PKG signing session not DONE and VALID`, 0, JSON.stringify(json));
	return {
		pubSignKey: json.pubSignKey,
		privSignKey: json.privSignKey
	};
}
