//#region src/recipients/builders.ts
function extractDomain(email) {
	return email.split("@")[1] || "";
}
/** Build the full attribute constraint list for a recipient. */
function buildCon(r) {
	return [...r._baseType === "email" ? [{
		t: "pbdf.sidn-pbdf.email.email",
		v: r.email
	}] : [{
		t: "pbdf.sidn-pbdf.email.domain",
		v: extractDomain(r.email)
	}], ...r._extras];
}
/** Build an encryption policy map from a list of recipients */
function buildEncryptionPolicy(recipients, timestamp) {
	const policy = {};
	for (const r of recipients) policy[r.email] = {
		ts: timestamp,
		con: buildCon(r)
	};
	return policy;
}
//#endregion
//#region src/signing/api-key.ts
/** Resolve signing keys using an API key */
async function resolveSigningKeysFromApiKey(pkgUrl, apiKey, headers) {
	return fetchSigningKeysWithApiKey(pkgUrl, apiKey, headers);
}
